  const form = document.getElementById('consent-form');
  const checkbox = document.getElementById('terms-consent');
  const errorText = document.getElementById('terms-error');

  form.addEventListener('submit', (event) => {
    event.preventDefault();

    if (!checkbox.checked) {
      // Show error, update aria-invalid state, and set focus
      checkbox.setAttribute('aria-invalid', 'true');
      errorText.hidden = false;
      checkbox.focus();
    } else {
      // Clean up error state on valid submission
      checkbox.removeAttribute('aria-invalid');
      errorText.hidden = true;

      // Normally, form.submit() or an API call would occur here
      console.log('Form is valid and ready to submit');
      alert('Registration complete!');
    }
  });

  // Clear the error message immediately as soon as the user checks the box
  checkbox.addEventListener('change', () => {
    if (checkbox.checked && checkbox.getAttribute('aria-invalid') === 'true') {
      checkbox.removeAttribute('aria-invalid');
      errorText.hidden = true;
    }
  });
});
